import React, { useEffect, useRef, useState } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {
  const scannerRef = useRef(null);
  const [student, setStudent] = useState(null);
  const [status, setStatus] = useState("");

  // Use a ref to track if we are currently processing a scan to prevent multiple pings
  const isProcessing = useRef(false);

  useEffect(() => {
    // 1. Initialize the scanner instance
    const html5QrCode = new Html5Qrcode("reader");
    scannerRef.current = html5QrCode;

    const startScanner = async () => {
      try {
        await html5QrCode.start(
          { facingMode: "environment" },
          {
            fps: 20, // Increased FPS for faster response
            qrbox: { width: 250, height: 250 },
          },
          onScanSuccess
        );
        setIsScanning(true);
      } catch (err) {
        console.error("Failed to start scanner:", err);
      }
    };

    // Small delay to ensure the DOM element #reader is actually ready
    const timer = setTimeout(() => {
      startScanner();
    }, 500);

    return () => {
      clearTimeout(timer);
      if (scannerRef.current && scannerRef.current.isScanning) {
        scannerRef.current
          .stop()
          .then(() => {
            console.log("Scanner stopped");
          })
          .catch((err) => console.error("Stop failed", err));
      }
    };
  }, []);

  const onScanSuccess = async (decodedText) => {
    // If we are already processing a previous scan, ignore this one
    if (isProcessing.current) return;

    isProcessing.current = true;
    console.log("Scanned:", decodedText);

    try {
      // Step 1: Verify User
      const verify = await fetch(`http://localhost:5000/verify-user/${decodedText}`);
      const verifyData = await verify.json();

      if (!verifyData.success) {
        setStudent(null);
        setStatus("notfound");
      } else {
        setStudent(verifyData.user);

        // Step 2: Mark Attendance
        const attendance = await fetch(
          `http://localhost:5000/mark-attendance/${decodedText}`,
          { method: "PUT" }
        );
        const attendanceData = await attendance.json();

        if (attendanceData.success) {
          setStatus("success");
        } else {
          setStatus("already");
        }
      }
    } catch (err) {
      console.error(err);
      setStatus("servererror");
    } finally {
      // Wait 3 seconds before allowing another scan
      setTimeout(() => {
        isProcessing.current = false;
      }, 3000);
    }
  };

  return (
    <div style={{ textAlign: "center", marginTop: "40px", fontFamily: "sans-serif" }}>
      <h2>QR Attendance Scanner</h2>
      
      <div
        id="reader"
        style={{
          width: "100%",
          maxWidth: "400px",
          margin: "auto",
          border: "2px solid #333",
          borderRadius: "8px",
          overflow: "hidden",
          backgroundColor: "#f0f0f0"
        }}
      ></div>

      <div style={{ marginTop: "20px", minHeight: "100px" }}>
        {status === "servererror" && <h3 style={{ color: "red" }}>⚠️ Server Error</h3>}
        
        {student && (
          <div style={{ padding: "15px", border: "1px solid #ddd", display: "inline-block", borderRadius: "10px" }}>
            <h3 style={{ margin: "5px 0" }}>{student.name}</h3>
            <p style={{ color: "#666" }}>{student.college_name}</p>

            {status === "success" && <h2 style={{ color: "green" }}>✔ Attendance Marked</h2>}
            {status === "already" && <h2 style={{ color: "orange" }}>Already Scanned</h2>}
          </div>
        )}

        {!student && status === "notfound" && (
          <h2 style={{ color: "red" }}>❌ User Not Found</h2>
        )}
      </div>

      <button 
        onClick={() => window.location.reload()}
        style={{ marginTop: "20px", padding: "10px 20px", cursor: "pointer" }}
      >
        Refresh Scanner
      </button>
    </div>
  );
}

export default QRScanner;
